// GERADO por scripts/build-gate-worker.mjs. Não editar à mão.
// Site "em construção" no Cloudflare Worker: sem a palavra-passe (secret SITE_PASSWORD) só se vê a página de bloqueio.
// O acesso fica guardado 30 dias num cookie assinado (HMAC-SHA256).

const COOKIE = 'tufeisep_acesso';
const DAYS = 30;
const HTML = "<!doctype html>\n<html lang=\"pt\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <meta name=\"robots\" content=\"noindex\">\n  <title>Em construção · TUFEISEP</title>\n  <link rel=\"icon\" type=\"image/png\" href=\"/bloqueado/favicon.png\">\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Instrument+Serif:ital@0;1&family=Manrope:wght@400;500;600;700;800&display=swap\">\n  <link rel=\"stylesheet\" href=\"/bloqueado/bloqueado.css\">\n</head>\n<body>\n  <main class=\"cena\">\n    <div class=\"imagem\" role=\"img\" aria-label=\"Fachada de tijolo com janelas em grelha e linhas de projeto\"></div>\n    <section class=\"cartao\">\n      <img class=\"logo\" src=\"/bloqueado/logo.webp\" alt=\"Tuna Feminina do ISEP\" width=\"120\" height=\"120\">\n      <p class=\"etiqueta\">Tuna Feminina do ISEP</p>\n      <h1>Em <em>construção</em></h1>\n      <p class=\"texto\">Estamos a preparar o novo site da TUFEISEP. Volta em breve.</p>\n      <form id=\"form\" autocomplete=\"off\">\n        <label for=\"pw\">Já tens acesso?</label>\n        <div class=\"campo\">\n          <input id=\"pw\" name=\"palavraPasse\" type=\"password\" placeholder=\"Palavra-passe\" required autocomplete=\"current-password\">\n          <button type=\"submit\">Entrar</button>\n        </div>\n        <p id=\"erro\" class=\"erro\" role=\"alert\" hidden></p>\n      </form>\n    </section>\n  </main>\n  <script src=\"/bloqueado/bloqueado.js\"></script>\n</body>\n</html>\n";
const ASSETS = {"/bloqueado/bloqueado.css":["text/css; charset=utf-8",":root { --tijolo: #bc6751; --cinza: #414141; --bege: #eee4d6; --rosa: #dcb0a1; }\n* { box-sizing: border-box; }\nbody { margin: 0; font: 400 16px/1.6 \"Manrope\", ui-sans-serif, system-ui, sans-serif; color: var(--cinza); background: var(--tijolo); -webkit-font-smoothing: antialiased; }\n.cena { min-height: 100vh; min-height: 100dvh; display: grid; place-items: center; padding: 24px; position: relative; }\n.imagem { position: fixed; inset: 0; background: url(\"/bloqueado/fachada.svg\") center / cover; }\n.imagem::after { content: \"\"; position: absolute; inset: 0; background: radial-gradient(circle at 50% 45%, rgba(43,42,41,0) 0, rgba(43,42,41,.45) 100%); }\n.cartao { position: relative; width: min(440px, 100%); text-align: center; padding: 40px 32px 32px; background: rgba(252, 250, 247, .94); backdrop-filter: blur(10px); border-radius: 22px; box-shadow: 0 30px 70px -20px rgba(43, 20, 12, .55); }\n.logo { width: 96px; height: 96px; object-fit: contain; margin: 0 auto 8px; display: block; }\n.etiqueta { margin: 0; font-size: 12px; font-weight: 700; letter-spacing: .16em; text-transform: uppercase; color: var(--tijolo); }\nh1 { margin: 6px 0 10px; font: 400 clamp(40px, 9vw, 54px)/1.05 \"Instrument Serif\", Georgia, serif; }\nh1 em { color: var(--tijolo); }\n.texto { margin: 0 0 28px; color: #80776f; }\nform { border-top: 1px solid #ece5dc; padding-top: 22px; }\nlabel { display: block; margin-bottom: 8px; font-size: 13px; font-weight: 600; color: #80776f; }\n.campo { display: flex; gap: 8px; }\ninput { flex: 1; min-width: 0; padding: 12px 14px; font: inherit; color: var(--cinza); background: #fff; border: 1px solid #e0d6ca; border-radius: 12px; }\ninput:focus { outline: 2px solid var(--tijolo); outline-offset: 1px; border-color: transparent; }\nbutton { padding: 12px 20px; font: 700 15px/1 \"Manrope\", sans-serif; color: #fff; background: var(--tijolo); border: 0; border-radius: 12px; cursor: pointer; }\nbutton:hover { background: #a85a46; }\nbutton:disabled { opacity: .6; cursor: wait; }\n.erro { margin: 10px 0 0; font-size: 14px; color: #9a4c39; }\n@media (max-width: 420px) { .campo { flex-direction: column; } .cartao { padding: 32px 22px 24px; } }\n",false],"/bloqueado/bloqueado.js":["text/javascript; charset=utf-8","const form = document.getElementById('form');\nconst erro = document.getElementById('erro');\nconst botao = form.querySelector('button');\n\nform.addEventListener('submit', async e => {\n  e.preventDefault();\n  erro.hidden = true;\n  botao.disabled = true;\n  try {\n    const r = await fetch('/bloqueado/entrar', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ palavraPasse: form.palavraPasse.value }),\n    });\n    if (r.ok) return location.reload();\n    erro.textContent = (await r.json().catch(() => ({}))).erro || 'Não foi possível entrar.';\n  } catch {\n    erro.textContent = 'Sem ligação. Tenta outra vez.';\n  }\n  erro.hidden = false;\n  botao.disabled = false;\n  form.palavraPasse.select();\n});\n",false],"/bloqueado/fachada.svg":["image/svg+xml","<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 1000\" preserveAspectRatio=\"xMidYMid slice\">\n  <defs>\n    <linearGradient id=\"c\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#d9856d\"/><stop offset=\"1\" stop-color=\"#8f3f2c\"/></linearGradient>\n    <pattern id=\"t\" width=\"40\" height=\"20\" patternUnits=\"userSpaceOnUse\">\n      <rect width=\"40\" height=\"20\" fill=\"none\" stroke=\"#000\" stroke-opacity=\".12\" stroke-width=\"1\"/>\n      <path d=\"M20 0v20\" stroke=\"#000\" stroke-opacity=\".12\"/>\n    </pattern>\n    <pattern id=\"g\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\"><path d=\"M40 0H0V40\" fill=\"none\" stroke=\"#fff\" stroke-opacity=\".09\"/></pattern>\n  </defs>\n  <rect width=\"800\" height=\"1000\" fill=\"url(#c)\"/>\n  <rect width=\"800\" height=\"1000\" fill=\"url(#t)\"/>\n  <rect width=\"800\" height=\"1000\" fill=\"url(#g)\"/>\n  <!-- janelas da fachada, em grelha como o edifício do ISEP -->\n  <g fill=\"#2b2a29\" fill-opacity=\".78\">\n    <g id=\"r\"><rect x=\"60\" y=\"120\" width=\"70\" height=\"130\"/><rect x=\"170\" y=\"120\" width=\"70\" height=\"130\"/><rect x=\"280\" y=\"120\" width=\"70\" height=\"130\"/><rect x=\"390\" y=\"120\" width=\"70\" height=\"130\"/><rect x=\"500\" y=\"120\" width=\"70\" height=\"130\"/><rect x=\"610\" y=\"120\" width=\"70\" height=\"130\"/></g>\n    <use href=\"#r\" y=\"200\"/><use href=\"#r\" y=\"400\"/><use href=\"#r\" y=\"600\"/>\n  </g>\n  <g fill=\"#eee4d6\" fill-opacity=\".16\"><use href=\"#r\" y=\"200\"/><use href=\"#r\" y=\"600\"/></g>\n  <!-- linhas de projeto -->\n  <g stroke=\"#eee4d6\" stroke-opacity=\".5\" fill=\"none\" stroke-width=\"1.5\" stroke-dasharray=\"6 6\">\n    <path d=\"M30 60H770M30 940H770M30 60V940M770 60V940\"/>\n    <circle cx=\"400\" cy=\"500\" r=\"330\"/>\n  </g>\n  <g stroke=\"#eee4d6\" stroke-opacity=\".6\" stroke-width=\"2\"><path d=\"M30 60v-20M770 60v-20M30 940v20M770 940v20\"/></g>\n</svg>\n",false],"/bloqueado/logo.webp":["image/webp","",true],"/bloqueado/favicon.png":["image/png","",true]};

const enc = new TextEncoder();
const hex = buf => [...new Uint8Array(buf)].map(b => b.toString(16).padStart(2, '0')).join('');
const hmac = async (secret, msg) => {
  const k = await crypto.subtle.importKey('raw', enc.encode('tufeisep-gate' + secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  return hex(await crypto.subtle.sign('HMAC', k, enc.encode(msg)));
};
const same = async (a, b) => (await hmac('cmp', a)) === (await hmac('cmp', b));

async function hasAccess(request, secret) {
  const raw = (request.headers.get('cookie') || '').split(';').map(c => c.trim()).find(c => c.startsWith(COOKIE + '='));
  if (!raw) return false;
  const [exp, sig] = raw.slice(COOKIE.length + 1).split('.');
  return Boolean(exp && sig) && Number(exp) > Date.now() && await same(sig, await hmac(secret, exp));
}

const json = (body, status = 200, headers = {}) =>
  new Response(JSON.stringify(body), { status, headers: { 'content-type': 'application/json', ...headers } });

export default {
  async fetch(request, env) {
    const secret = env.SITE_PASSWORD;
    if (!secret) return fetch(request); // sem palavra-passe definida, o site fica aberto
    const url = new URL(request.url);

    const asset = ASSETS[url.pathname];
    if (asset && request.method === 'GET') {
      const [type, data, binary] = asset;
      const body = binary ? Uint8Array.from(atob(data), c => c.charCodeAt(0)) : data;
      return new Response(body, { headers: { 'content-type': type, 'cache-control': 'public, max-age=86400' } });
    }

    if (url.pathname === '/bloqueado/entrar' && request.method === 'POST') {
      const { palavraPasse } = await request.json().catch(() => ({}));
      if (!(await same(palavraPasse ?? '', secret))) return json({ erro: 'Palavra-passe errada.' }, 401);
      const exp = Date.now() + DAYS * 864e5;
      return json({ ok: true }, 200, {
        'set-cookie': `${COOKIE}=${exp}.${await hmac(secret, String(exp))}; Max-Age=${DAYS * 86400}; Path=/; HttpOnly; Secure; SameSite=Lax`,
      });
    }

    if (await hasAccess(request, secret)) return fetch(request);

    return new Response(HTML, {
      status: 503,
      headers: { 'content-type': 'text/html; charset=utf-8', 'retry-after': '86400', 'cache-control': 'no-store', 'x-robots-tag': 'noindex' },
    });
  },
};
